namespace OPEN_LRD.Nodes.Links
{
    /// <summary>Identifies the processes that contributed a graph link.</summary>
    [Flags]
    public enum LinkOrigin
    {
        /// <summary>The link has no recorded origin.</summary>
        None = 0,
        /// <summary>The link was explicitly supplied by a caller or import.</summary>
        Explicit = 1,
        /// <summary>The link was generated from node metadata.</summary>
        NodeMetadata = 2,
        /// <summary>The link was generated by reasoning.</summary>
        Reasoning = 4
    }
}
